items=[]
def argument():
    print('argument')
    return 3
try: items.append(value=argument())
except TypeError: print('keyword')
print(items)

items=[]
method=items.append
try: method(value=3)
except TypeError: print('keyword')
method(4)
print(items)

items=[]
try: list.append(items,value=3)
except TypeError: print('keyword')
list.append(items,4)
print(items)

items=[]
for method in [items.append,list.append.__get__(items,list)]:
    try: method(**{'value':3})
    except TypeError: print('keyword')
try: list.append(items,**{'value':4})
except TypeError: print('keyword')
print(items)

items=[]
try: items.append()
except TypeError: print('missing')
try: items.append(1,2)
except TypeError: print('extra')
try: items.append(1,value=2)
except TypeError: print('duplicate')
try: items.append(object=3)
except TypeError: print('keyword')
items.append(*(4,))
print(items)

class C:
    def append(self,value): return value+1
print(C().append(value=3))

class C:
    append=[]
def argument():
    print('argument')
    return 3
try: C().append(argument())
except TypeError: print('not-callable')

class C:
    def append(self,value): print('old',value)
c=C()
def replacement(self,value): print('new',value)
def argument():
    C.append=replacement
    return 3
c.append(argument())
c.append(4)
